const body = ($input.first().json && $input.first().json.body) || {};

const rawWorkspace = body.workspace_id;
const rawQuestion = body.research_question;
const rawMax = body.max_papers;

const workspace_id = Number(rawWorkspace);
const research_question = typeof rawQuestion === 'string' ? rawQuestion.trim() : (rawQuestion == null ? '' : String(rawQuestion).trim());

let max_papers = (rawMax === undefined || rawMax === null || rawMax === "") ? 10 : Number(rawMax);
if (!Number.isFinite(max_papers)) { max_papers = 10; }
if (max_papers > 20) { max_papers = 20; }

return [{ json: { workspace_id, research_question, max_papers } }];

const j = $input.first().json || {};
const workspace_id = j.workspace_id;
const research_question = j.research_question;
const max_papers = j.max_papers;

const errors = [];
if (!Number.isInteger(workspace_id) || workspace_id <= 0) {
  errors.push('workspace_id must be a positive integer');
}
if (typeof research_question !== 'string' || research_question.length === 0) {
  errors.push('research_question must be a non-empty string');
}
if (!Number.isInteger(max_papers) || max_papers < 1 || max_papers > 20) {
  errors.push('max_papers must be an integer between 1 and 20');
}

const is_valid = errors.length === 0;
return [{ json: {
  workspace_id,
  research_question,
  max_papers,
  is_valid,
  error: is_valid ? null : errors.join('; '),
} }];

const ctx = $('Validate Synthesis Input').first().json || {};
const papers = $input.all()
  .map(i => i.json)
  .filter(j => j && j.id != null);

return [{ json: {
  workspace_id: ctx.workspace_id,
  research_question: ctx.research_question,
  max_papers: ctx.max_papers,
  papers,
  paper_count: papers.length,
} }];

const agg = $('Aggregate Papers').first().json || {};
const papers = agg.papers || [];

const analyses = $('Fetch Paper Analyses').all()
  .map(i => i.json)
  .filter(j => j && j.paper_id != null);

const byPaper = {};
for (const a of analyses) { byPaper[a.paper_id] = a; }

const evidence = papers.map(p => {
  const a = byPaper[p.id];
  const base = {
    paper_id: p.id,
    title: p.title,
    authors: p.authors,
    abstract: p.abstract,
    publication_date: p.publication_date,
    venue: p.venue,
    paper_url: p.paper_url,
  };
  if (!a) {
    return Object.assign(base, { analysis_available: false });
  }
  return Object.assign(base, {
    analysis_available: true,
    summary: a.summary,
    key_contributions: a.key_contributions,
    methodology: a.methodology,
    datasets: a.datasets,
    models_used: a.models_used,
    limitations: a.limitations,
    future_work: a.future_work,
    keywords: a.keywords,
    research_gaps: a.research_gaps,
  });
});

const analyzed_evidence = evidence.filter(e => e.analysis_available);
const papers_considered = analyzed_evidence.map(e => e.paper_id);

return [{ json: {
  workspace_id: agg.workspace_id,
  research_question: agg.research_question,
  max_papers: agg.max_papers,
  evidence,
  analyzed_evidence,
  analyzed_count: analyzed_evidence.length,
  papers_considered,
} }];

