const j = $input.first().json || {};

// Extract raw text from the various OpenAI response shapes
let raw = null;
if (j.output && j.output[0] && j.output[0].content && j.output[0].content[0]) {
  raw = j.output[0].content[0].text;
}
if (raw == null) raw = j.output_text;
if (raw == null) raw = j.text;
if (raw == null && j.message) raw = j.message.content;
if (raw == null && j.content) raw = j.content;
if (raw == null && typeof j === 'object' && j.overview) raw = j;

let parsed = null;
let parse_ok = true;
try {
  if (raw && typeof raw === 'object') { parsed = raw; }
  else if (typeof raw === 'string') { parsed = JSON.parse(raw); }
  else { parse_ok = false; }
} catch (e) { parse_ok = false; }

const required = ['research_question','overview','key_themes','major_findings','comparison','research_gaps','limitations','conclusion','papers_considered'];
let missing = [];
if (parse_ok && parsed) {
  missing = required.filter(k => !(k in parsed));
} else {
  missing = required.slice();
}

const is_valid_output = parse_ok && parsed != null && missing.length === 0;

return [{ json: {
  is_valid_output,
  missing,
  synthesis: parsed,
} }];

const ctx = $('Prepare Research Evidence').first().json || {};
const s = ($input.first().json && $input.first().json.synthesis) || {};

return [{ json: {
  success: true,
  message: 'Research synthesis generated successfully',
  workspace_id: ctx.workspace_id,
  research_question: ctx.research_question,
  papers_considered: s.papers_considered || ctx.papers_considered || [],
  synthesis: {
    overview: s.overview,
    key_themes: s.key_themes,
    major_findings: s.major_findings,
    comparison: s.comparison,
    research_gaps: s.research_gaps,
    limitations: s.limitations,
    conclusion: s.conclusion,
  },
} }];

return [{ json: {
  success: false,
  message: 'Research synthesis failed',
} }];

